import{_ as a,c as s,o as t,a2 as i}from"./chunks/framework.PGES7OoM.js";const u=JSON.parse('{"title":"Curvy SDK","description":"A typed, functional SDK for building private asset flows with Curvy.","frontmatter":{"title":"Curvy SDK","description":"A typed, functional SDK for building private asset flows with Curvy.","rawMarkdown":"---\\ntitle: Curvy SDK\\ndescription: A typed, functional SDK for building private asset flows with Curvy.\\n---\\n\\n# Curvy SDK\\n\\nThe Curvy SDK is a framework-agnostic TypeScript interface for private transfers, swaps, withdrawals, and recovery. It provides a small configuration layer and standalone actions with typed parameters and results.\\n\\n```ts\\nimport { createBrowserCurvyConfig } from \\"@0xcurvy/curvy-sdk/config\\";\\nimport { getBalances } from \\"@0xcurvy/curvy-sdk/actions\\";\\n\\nconst config = await createBrowserCurvyConfig();\\nconst balances = await getBalances({ config });\\n```\\n\\n## Overview\\n\\nThe SDK is organized around two concepts:\\n\\n- A [`CurvyConfig`](/sdk/config/) owns network metadata, storage, account state, API clients, proving, and lifecycle.\\n- [Actions](/sdk/actions/) are standalone functions that read or change protocol state through a config.\\n\\nThis keeps the API composable: applications can use the ambient browser config for convenience or pass an explicit config for tests, servers, and multi-instance processes.\\n\\n## Design goals\\n\\n### Typed\\n\\nParameters, results, events, plans, networks, and protocol values are TypeScript-first. Action pages show the exact public signatures and are generated from the SDK source.\\n\\n### Composable\\n\\nHigh-level actions such as [`aggregate`](/sdk/actions/aggregator/aggregate) and [`executeIntent`](/sdk/actions/planner/executeIntent) cover common flows. Lower-level actions remain available when an application needs to inspect, submit, or relay intermediate results itself.\\n\\n### Runtime-aware\\n\\nBrowser and server constructors choose safe defaults for storage, session handling, and ambient state. The same actions work in both environments.\\n\\n### Explicit about lifecycle\\n\\nA config can own timers, listeners, caches, and a proving runtime. Destroy it when its lifetime ends.\\n\\n## Documentation\\n\\n- [Getting started](/sdk/getting-started) installs the package and runs the first action.\\n- [Config](/sdk/config/) explains browser, server, and custom configuration.\\n- [Actions](/sdk/actions/) introduces the action model and links to every public action.\\n- [TypeScript](/sdk/typescript) covers inference, imports, literal types, and `bigint` values.\\n- [Developer guides](/for-programmers/) combine actions into complete application flows.\\n- [Payments SDK](/sdk/payments/) is a **separate** package for shops accepting Curvy checkout — not part of this wallet SDK.\\n","rawMarkdownPath":"/_raw/sdk/index.md","rawMarkdownTitle":"Curvy SDK","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/index.md"},"headers":[],"relativePath":"sdk/index.md","filePath":"sdk/index.md","lastUpdated":1789993443000}'),n={name:"sdk/index.md"};function r(o,e,l,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="curvy-sdk" tabindex="-1">Curvy SDK <a class="header-anchor" href="#curvy-sdk" aria-label="Permalink to &quot;Curvy SDK&quot;">​</a></h1><p>The Curvy SDK is a framework-agnostic TypeScript interface for private transfers, swaps, withdrawals, and recovery. It provides a small configuration layer and standalone actions with typed parameters and results.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createBrowserCurvyConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@0xcurvy/curvy-sdk/config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { getBalances } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@0xcurvy/curvy-sdk/actions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createBrowserCurvyConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> balances</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getBalances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ config });</span></span></code></pre></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The SDK is organized around two concepts:</p><ul><li>A <a href="/sdk/config/"><code>CurvyConfig</code></a> owns network metadata, storage, account state, API clients, proving, and lifecycle.</li><li><a href="/sdk/actions/">Actions</a> are standalone functions that read or change protocol state through a config.</li></ul><p>This keeps the API composable: applications can use the ambient browser config for convenience or pass an explicit config for tests, servers, and multi-instance processes.</p><h2 id="design-goals" tabindex="-1">Design goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design goals&quot;">​</a></h2><h3 id="typed" tabindex="-1">Typed <a class="header-anchor" href="#typed" aria-label="Permalink to &quot;Typed&quot;">​</a></h3><p>Parameters, results, events, plans, networks, and protocol values are TypeScript-first. Action pages show the exact public signatures and are generated from the SDK source.</p><h3 id="composable" tabindex="-1">Composable <a class="header-anchor" href="#composable" aria-label="Permalink to &quot;Composable&quot;">​</a></h3><p>High-level actions such as <a href="/sdk/actions/aggregator/aggregate.html"><code>aggregate</code></a> and <a href="/sdk/actions/planner/executeIntent.html"><code>executeIntent</code></a> cover common flows. Lower-level actions remain available when an application needs to inspect, submit, or relay intermediate results itself.</p><h3 id="runtime-aware" tabindex="-1">Runtime-aware <a class="header-anchor" href="#runtime-aware" aria-label="Permalink to &quot;Runtime-aware&quot;">​</a></h3><p>Browser and server constructors choose safe defaults for storage, session handling, and ambient state. The same actions work in both environments.</p><h3 id="explicit-about-lifecycle" tabindex="-1">Explicit about lifecycle <a class="header-anchor" href="#explicit-about-lifecycle" aria-label="Permalink to &quot;Explicit about lifecycle&quot;">​</a></h3><p>A config can own timers, listeners, caches, and a proving runtime. Destroy it when its lifetime ends.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li><a href="/sdk/getting-started.html">Getting started</a> installs the package and runs the first action.</li><li><a href="/sdk/config/">Config</a> explains browser, server, and custom configuration.</li><li><a href="/sdk/actions/">Actions</a> introduces the action model and links to every public action.</li><li><a href="/sdk/typescript.html">TypeScript</a> covers inference, imports, literal types, and <code>bigint</code> values.</li><li><a href="/for-programmers/">Developer guides</a> combine actions into complete application flows.</li><li><a href="/sdk/payments/">Payments SDK</a> is a <strong>separate</strong> package for shops accepting Curvy checkout — not part of this wallet SDK.</li></ul>`,18)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
